import {
    _decorator, Component, Node, Vec3, input, Input, EventKeyboard, KeyCode,
    Quat, Camera, geometry, PhysicsSystem, math,
} from 'cc';
import { PlayerStats } from './PlayerStats';
const { ccclass, property } = _decorator;

enum MoveState { Idle, Run, Jump, DoubleJump, Slide, Attack }

@ccclass('PlayerController')
export class PlayerController extends Component {
    @property moveSpeed = 6;
    @property runSpeed = 9;
    @property jumpSpeed = 9;
    @property gravity = -22;
    @property slideSpeed = 12;
    @property slideDuration = 0.6;

    public stats: PlayerStats | null = null;
    public cameraNode: Node | null = null;

    private velocity: Vec3 = new Vec3();
    private moveInput: Vec3 = new Vec3();
    private keys: Set<KeyCode> = new Set();

    private grounded = true;
    private jumpsUsed = 0;
    private maxJumps = 2;
    private sliding = false;
    private slideTimer = 0;
    private slideDir: Vec3 = new Vec3();

    public state: MoveState = MoveState.Idle;
    public facingYaw = 0;

    // animation refs (set externally)
    public legs?: { l: Node, r: Node };
    public arms?: { l: Node, r: Node };
    public body?: Node;

    private animTime = 0;

    onLoad() {
        input.on(Input.EventType.KEY_DOWN, this.onKeyDown, this);
        input.on(Input.EventType.KEY_UP, this.onKeyUp, this);
    }

    onDestroy() {
        input.off(Input.EventType.KEY_DOWN, this.onKeyDown, this);
        input.off(Input.EventType.KEY_UP, this.onKeyUp, this);
    }

    private onKeyDown(e: EventKeyboard) {
        this.keys.add(e.keyCode);
        if (e.keyCode === KeyCode.SPACE) this.tryJump();
        if (e.keyCode === KeyCode.SHIFT_LEFT || e.keyCode === KeyCode.KEY_C) this.trySlide();
    }
    private onKeyUp(e: EventKeyboard) { this.keys.delete(e.keyCode); }

    private tryJump() {
        if (this.sliding) return;
        if (this.jumpsUsed < this.maxJumps) {
            this.velocity.y = this.jumpSpeed;
            this.jumpsUsed++;
            this.grounded = false;
            this.state = this.jumpsUsed === 2 ? MoveState.DoubleJump : MoveState.Jump;
        }
    }

    private trySlide() {
        if (this.sliding || !this.grounded) return;
        if (!this.stats || !this.stats.useStamina(20)) return;
        this.sliding = true;
        this.slideTimer = this.slideDuration;
        // slide in current move dir, or forward
        const dir = this.moveInput.lengthSqr() > 0.01 ? this.moveInput.clone().normalize() : this.getForward();
        this.slideDir.set(dir);
        this.state = MoveState.Slide;
    }

    private getForward(): Vec3 {
        const yaw = this.facingYaw * Math.PI / 180;
        return new Vec3(Math.sin(yaw), 0, Math.cos(yaw));
    }

    private computeMoveInput() {
        let x = 0, z = 0;
        if (this.keys.has(KeyCode.KEY_W)) z += 1;
        if (this.keys.has(KeyCode.KEY_S)) z -= 1;
        if (this.keys.has(KeyCode.KEY_A)) x -= 1;
        if (this.keys.has(KeyCode.KEY_D)) x += 1;

        // Map to camera-relative direction (camera looks down -Z generally)
        let camYaw = 0;
        if (this.cameraNode) {
            const e = new Vec3();
            Quat.toEuler(e, this.cameraNode.worldRotation);
            camYaw = e.y;
        }
        const rad = camYaw * Math.PI / 180;
        const fwdX = Math.sin(rad), fwdZ = Math.cos(rad);
        const rgtX = Math.cos(rad), rgtZ = -Math.sin(rad);
        this.moveInput.set(fwdX * z + rgtX * x, 0, fwdZ * z + rgtZ * x);
        if (this.moveInput.lengthSqr() > 1) this.moveInput.normalize();
    }

    update(dt: number) {
        if (!this.stats) return;
        this.stats.update(dt);
        this.computeMoveInput();

        const running = this.keys.has(KeyCode.SHIFT_RIGHT);
        let speed = running ? this.runSpeed : this.moveSpeed;

        if (this.sliding) {
            this.slideTimer -= dt;
            const t = this.slideTimer / this.slideDuration; // 1 -> 0
            const cur = this.slideSpeed * Math.max(0.2, t);
            this.velocity.x = this.slideDir.x * cur;
            this.velocity.z = this.slideDir.z * cur;
            if (this.slideTimer <= 0) {
                this.sliding = false;
                this.state = MoveState.Idle;
            }
        } else {
            this.velocity.x = this.moveInput.x * speed;
            this.velocity.z = this.moveInput.z * speed;
        }

        // Gravity
        this.velocity.y += this.gravity * dt;

        // Move
        const pos = this.node.position;
        const nx = pos.x + this.velocity.x * dt;
        const ny = pos.y + this.velocity.y * dt;
        const nz = pos.z + this.velocity.z * dt;

        // Simple ground at y=0
        const groundY = 0;
        if (ny <= groundY) {
            this.node.setPosition(nx, groundY, nz);
            this.velocity.y = 0;
            if (!this.grounded) {
                this.grounded = true;
                this.jumpsUsed = 0;
            }
        } else {
            this.node.setPosition(nx, ny, nz);
            this.grounded = false;
        }

        // Face movement direction
        if (this.moveInput.lengthSqr() > 0.01 && !this.sliding) {
            this.facingYaw = Math.atan2(this.moveInput.x, this.moveInput.z) * 180 / Math.PI;
            const q = new Quat();
            Quat.fromEuler(q, 0, this.facingYaw, 0);
            this.node.setRotation(q);
        }

        // Update state
        if (!this.sliding && this.grounded) {
            this.state = this.moveInput.lengthSqr() > 0.01 ? MoveState.Run : MoveState.Idle;
        }

        // Bound to a soft world radius
        const p = this.node.position;
        const r = 95;
        const len = Math.hypot(p.x, p.z);
        if (len > r) {
            const k = r / len;
            this.node.setPosition(p.x * k, p.y, p.z * k);
        }

        this.animate(dt);
    }

    private animate(dt: number) {
        this.animTime += dt;
        if (this.sliding && this.body) {
            this.body.setRotationFromEuler(-60, 0, 0);
            return;
        }
        if (this.body) this.body.setRotationFromEuler(0, 0, 0);

        const moving = this.state === MoveState.Run;
        const swing = moving ? Math.sin(this.animTime * 12) * 35 : 0;
        if (this.legs) {
            this.legs.l.setRotationFromEuler(swing, 0, 0);
            this.legs.r.setRotationFromEuler(-swing, 0, 0);
        }
        if (this.arms) {
            this.arms.l.setRotationFromEuler(-swing, 0, 0);
            this.arms.r.setRotationFromEuler(swing, 0, 0);
        }
    }
}